node --input-type=module -e '
import { slugify } from "./src/slug.js";
const cases = [
  ["Hello, World!", {}, "hello-world"],
  ["Café Déjà Vu", {}, "cafe-deja-vu"],
  ["東京 Station", {}, "東京-station"],
  ["alpha beta gamma", {maxLength:12}, "alpha-beta"],
  ["abcdefghij", {maxLength:5}, "abcde"],
  ["alpha beta gamma", {maxLength:10}, "alpha-beta"],
  ["alpha beta gamma", {maxLength:11}, "alpha-beta"],
  ["alpha beta gamma", {maxLength:5}, "alpha"],
  ["alpha beta gamma", {maxLength:6}, "alpha"],
  ["a.b c", {separator:"."}, "a.b.c"],
  ["a -- b", {separator:"--"}, "a--b"],
  ["!!!", {}, ""],
  ["@@@ foo", {maxLength: 3}, "foo"],
];
for (const [input, options, expected] of cases) {
  const actual = slugify(input, options);
  console.log(JSON.stringify(input), options, "=>", JSON.stringify(actual), actual === expected ? "OK" : `FAIL expected ${JSON.stringify(expected)}`);
}
for (const opts of [{separator:""},{separator:null},{maxLength:0},{maxLength:-1},{maxLength:1.5},{maxLength:"3"},{maxLength:null}]) {
  try { slugify("abc", opts); console.log("NO THROW", opts); }
  catch (e) { console.log("throws", opts, e.constructor.name); }
}
'

